import type { HTMLAttributes } from "react";

function part(base: string, className = "") { return `${base} ${className}`.trim(); }
export function Card({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={part("co-rounded-xl co-border co-border-black/15 co-bg-white co-text-black co-shadow-sm", className)} {...props} />; }
export function CardHeader({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={part("co-flex co-flex-col co-gap-1.5 co-p-6", className)} {...props} />; }
export function CardTitle({ className, ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h3 className={part("co-text-lg co-font-semibold co-leading-none", className)} {...props} />; }
export function CardDescription({ className, ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={part("co-text-sm co-text-black/60", className)} {...props} />; }
export function CardContent({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={part("co-px-6 co-pb-6", className)} {...props} />; }
export function CardFooter({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={part("co-flex co-items-center co-gap-3 co-px-6 co-pb-6", className)} {...props} />; }
